from typing import List

class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        # Initialize two smallest values to a large number
        min1 = float('inf')
        min2 = float('inf')

        # Find the two smallest prices in the array
        for price in prices:
            if price < min1:
                min2 = min1
                min1 = price
            elif price < min2:
                min2 = price

        # Calculate the sum of the two smallest prices
        total_cost = min1 + min2

        # If the total cost is within the budget, return leftover money
        if total_cost <= money:
            return money - total_cost
        else:
            return -1
